const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l =>l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h,i) => obj[h] = cols[i] ?? "");

  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json : { investimentos } }]

// Obtém a lista global de investimentos vindos do nó anterior
const listaInvestimentos = $input.first().json.investimentos || [];

// Processa a lista de clientes
return ($input.first().json.body?.clientes || []).map(data => {

  // Normaliza o perfil do cliente para facilitar a busca
  const perfilCliente = (data.perfil || '').trim();
  const perfilNorm = perfilCliente.toLowerCase();

  // Filtra os produtos da tabela que correspondem ao perfil do cliente
  const opcoesRecomendadas = listaInvestimentos.filter(inv => 
    (inv.perfil || '').trim().toLowerCase() === perfilNorm
  );

  let mensagem = '';
  let recomendacao = '';

  switch (perfilNorm) {
    case 'conservador':
      mensagem = `Olá, ${data.nome || 'Cliente'}! Identificamos seu perfil como Conservador. Seu foco principal é a segurança e estabilidade do seu patrimônio.`;
      break;

    case 'moderado':
      mensagem = `Olá, ${data.nome || 'Cliente'}! Seu perfil é Moderado, buscando um equilíbrio entre segurança e rentabilidade.`;
      break;

    case 'arrojado':
    case 'experiente':
      mensagem = `Olá, ${data.nome || 'Cliente'}! Seu perfil é Arrojado, com foco em maximizar o potencial de retorno e maior tolerância a risco.`;
      break;

    default:
      mensagem = `Olá, ${data.nome || 'Cliente'}! Bem-vindo aos nossos serviços financeiros.`;
      break;
  }

  // Se houver opções encontradas na tabela de investimentos, monta o texto das recomendações
  if (opcoesRecomendadas.length > 0) {
    const detalheProdutos = opcoesRecomendadas
      .map(item => `- ${item.produto}: Mínimo R$ ${item.minimo} (Rentabilidade: ${item.rentabilidade})`)
      .join('\n');

    recomendacao = `Com base no seu perfil ${perfilCliente}, selecionamos os seguintes produtos recomendados:\n${detalheProdutos}`;
  } else {
    recomendacao = 'Por favor, realize a sua avaliação de perfil de investidor (suitability) para receber orientações personalizadas.';
  }

  // Retorna a estrutura atualizada mantendo os dados originais do cliente
  return {
    json: {
      ...data,
      mensagem,
      recomendacao,
      opcoes_investimento: opcoesRecomendadas // Array com os objetos de investimento filtrados
    }
  };
});

// Processa todos os itens recebidos no fluxo
return $input.all().map(item => {
  const cliente = item.json;

  // Trata o saldo numérico apenas internamente para validação de disponibilidade
  const saldoNumerico = parseFloat(
    (cliente.saldo || '0')
      .replace(/[^\d,-]/g, '')
      .replace('.', '')
      .replace(',', '.')
  ) || 0;

  // Trata a lista de investimentos com foco no aporte mínimo e rentabilidade
  const opcoesComCalculo = (cliente.opcoes_investimento || []).map(opt => {
    const minimo = Number(opt.minimo) || 0;
    const disponivel = saldoNumerico >= minimo;

    return {
      produto: opt.produto,
      aporte_minimo: `R$ ${minimo.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`,
      rentabilidade: opt.rentabilidade,
      disponivel_para_cliente: disponivel
    };
  });

  // Prompt do sistema ajustado (sem saldo, com foco no aporte mínimo)
  const systemPrompt = `Você é um especialista em investimentos e assistente virtual.
Sua resposta DEVE ser estritamente um objeto JSON com o seguinte formato:
{
  "email": "email do cliente"
  "assunto": "Título do e-mail impactante e profissional",
  "corpo": [
    "Parágrafo 1: Saudação e introdução ao perfil do cliente.",
    "Parágrafo 2: Apresentação detalhada de cada opção de investimento, destacando o produto, rentabilidade e o aporte mínimo necessário.",
    "Parágrafo 3: Fechamento e chamada para ação."
  ]
}

Diretrizes obrigatórias:
1. Tom de voz: Sempre amigável, acolhedor e profissional.
2. Idioma: Português do Brasil (PT-BR).
3. Restrição de tamanho: Cada parágrafo do corpo deve ter NO MÁXIMO de 4 a 6 linhas.
4. Conteúdo: Mencione os produtos recomendados informando claramente o aporte mínimo e a rentabilidade de cada um.
5. RESTRIÇÃO IMPORTANTE: NUNCA mencione o valor do saldo do cliente no e-mail.
6. Proibições: NUNCA use linguagem agressiva ou coercitiva. NUNCA faça promessas de ganhos garantidos ou retornos fixos em renda variável.`;

  // Dados enviados para a IA sem o campo de saldo
  const userPrompt = JSON.stringify({
    cliente: {
      email: cliente.email,
      nome: cliente.nome,
      perfil: cliente.perfil
    },
    investimentos: opcoesComCalculo
  }, null, 2);

  return {
    json: {
      system_prompt: systemPrompt,
      user_prompt: userPrompt,
      formato_resposta_esperado: {
        assunto: "string",
        corpo: ["string"]
      },
      dados_originais: cliente
    }
  };
});

// Processa a saída recebida do nó da LLM
return $input.all().map(item => {
  const llmOutput = item.json;

  // 1. Acessa o texto retornado dentro da estrutura do modelo
  const rawText = llmOutput.output?.[0]?.content?.[0]?.text || '';

  // 2. Limpa as marcações de bloco de código Markdown (```json ... ```)
  const cleanJsonString = rawText
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  let emailParsed = {
    email: '',
    assunto: 'Recomendações de Investimento',
    corpo: []
  };

  // 3. Converte a string JSON para um objeto JavaScript
  try {
    emailParsed = JSON.parse(cleanJsonString);
  } catch (error) {
    emailParsed.corpo = [cleanJsonString];
  }

  // 4. Obtém o e-mail prioritariamente do JSON da LLM, com fallback para os dados originais
  const emailDestinatario = emailParsed.email || llmOutput.dados_originais?.email || '';

  // 5. Formata o corpo em Texto Simples (mantendo quebras de linha entre parágrafos)
  const emailTexto = (emailParsed.corpo || []).join('\n\n');

  // 6. Formata o corpo em HTML estruturado com parágrafos e converte negritos (**texto**)
  const emailHtml = (emailParsed.corpo || [])
    .map(p => `<p style="font-family: Arial, sans-serif; font-size: 14px; line-height: 1.6; color: #333333;">${p.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')}</p>`)
    .join('');

  // Retorna os campos prontos para serem usados diretamente no nó de envio de e-mail do n8n
  return {
    json: {
      email_destinatario: emailDestinatario,
      assunto: emailParsed.assunto,
      corpo_texto: emailTexto,
      corpo_html: emailHtml,
      paragrafos: emailParsed.corpo
    }
  };
});
